"use client";

import { useId, useState, type ComponentProps } from "react";
import { Check } from "lucide-react";
import { cn } from "cn";
import { Badge } from "../components/badge";
import { Card } from "../components/card";
import { Button } from "../components/button";

interface PricingProps extends Omit<ComponentProps<"section">, "title"> {
  title?: string;
  description?: string;
  defaultBilling?: "monthly" | "yearly";
  plans?: {
    name: string;
    description: string;
    monthlyPrice: number;
    yearlyPrice: number;
    features: string[];
    href: string;
    label?: string;
    featured?: boolean;
  }[];
}

export function PricingCompact({
  title = "A plan for every next step",
  description = "Start small. Make room as you grow.",
  defaultBilling = "monthly",
  plans = [
    {
      name: "Starter",
      description: "For your next side project.",
      monthlyPrice: 0,
      yearlyPrice: 0,
      features: ["1 workspace", "Core components", "Community support"],
      href: "/signup",
      label: "Start for free",
    },
    {
      name: "Pro",
      description: "For ideas ready to grow.",
      monthlyPrice: 19,
      yearlyPrice: 15,
      features: ["Unlimited workspaces", "All components and blocks", "Priority support"],
      href: "/signup?plan=pro",
      featured: true,
    },
    {
      name: "Team",
      description: "For building together.",
      monthlyPrice: 49,
      yearlyPrice: 39,
      features: ["Everything in Pro", "Team collaboration", "Dedicated support"],
      href: "/signup?plan=team",
    },
  ],
  className,
  children,
  ...props
}: PricingProps = {}) {
  const [billing, setBilling] = useState(defaultBilling);
  const id = useId();
  const actionClass =
    "inline-flex min-h-11 w-full items-center justify-center border border-border px-4 py-2 text-sm font-semibold focus-visible:outline-2 focus-visible:outline-ring";
  function price(plan: (typeof plans)[number]) {
    return billing === "yearly" ? plan.yearlyPrice : plan.monthlyPrice;
  }
  return (
    <section
      {...props}
      aria-labelledby={props["aria-labelledby"] ?? `${id}-title`}
      data-slot="pricing"
      data-layout="compact"
      className={cn("@container w-full space-y-8 text-foreground", className)}
    >
      <div className="text-center">
        <h2 id={`${id}-title`} className={"typography-section-title"}>
          {title}
        </h2>
        <p className={`mt-3 typography-body`}>{description}</p>
      </div>
      <div role="group" aria-label="Billing period" className="flex justify-center gap-1">
        <Button
          variant={billing === "monthly" ? "primary" : "secondary"}
          aria-pressed={billing === "monthly"}
          onClick={() => setBilling("monthly")}
        >
          Monthly
        </Button>
        <Button
          variant={billing === "yearly" ? "primary" : "secondary"}
          aria-pressed={billing === "yearly"}
          onClick={() => setBilling("yearly")}
        >
          Yearly
        </Button>
      </div>
      <p aria-live="polite" className="text-center text-xs text-muted-foreground">
        {billing === "yearly"
          ? "Monthly prices shown. Billed once a year."
          : "Billed monthly. Switch to yearly for lower monthly prices."}
      </p>
      {
        <div className={cn("grid gap-4", "grid-cols-1")}>
          {plans.map((plan) => (
            <Card
              key={plan.name}
              title=""
              description=""
              className={cn("max-w-none!", plan.featured && "border-primary")}
            >
              <div className="grid items-center gap-6 @xl:grid-cols-[1fr_1.5fr_auto]">
                <div>
                  <div className="flex flex-wrap items-center gap-3">
                    <h3 className={"typography-subsection-title"}>{plan.name}</h3>
                    {plan.featured && <Badge variant="info">Popular</Badge>}
                  </div>
                  <p className={`mt-2 typography-body`}>{plan.description}</p>
                  <p className="mt-5">
                    <span className="text-3xl font-semibold">${price(plan)}</span>
                    <span className="text-xs text-muted-foreground"> / month</span>
                  </p>
                  {billing === "yearly" && (
                    <p className="mt-1 text-xs text-muted-foreground">
                      ${price(plan) * 12} billed yearly
                    </p>
                  )}
                </div>
                <ul className="mt-6 space-y-3 text-sm">
                  {plan.features.map((feature) => (
                    <li key={feature} className="flex items-start gap-2">
                      <Check
                        size={16}
                        aria-hidden="true"
                        className="mt-0.5 shrink-0 text-secondary dark:text-primary"
                      />
                      {feature}
                    </li>
                  ))}
                </ul>
                {
                  <a
                    href={plan.href}
                    aria-label={`${plan.label ?? "Get started"} with ${plan.name}`}
                    className={cn(
                      actionClass,
                      "w-auto whitespace-nowrap",
                      plan.featured
                        ? "bg-primary text-primary-foreground hover:bg-primary/90"
                        : "hover:bg-muted",
                    )}
                  >
                    {plan.label ?? "Get started"}
                  </a>
                }
              </div>
            </Card>
          ))}
        </div>
      }
      {children}
    </section>
  );
}

"use client";

import { memo, type ReactNode } from "react";
import * as motion from "motion/react-client";
import { useReducedMotion, type HTMLMotionProps } from "motion/react";
import {
  CircleCheck,
  CircleDashed,
  CircleX,
  Clock3,
  SearchCheck,
  Send,
  TriangleAlert,
} from "lucide-react";

interface BadgeProps extends Omit<HTMLMotionProps<"span">, "children"> {
  children?: ReactNode;
  variant?:
    | "pending"
    | "in-progress"
    | "submitted"
    | "in-review"
    | "success"
    | "failed"
    | "expired"
    | "neutral"
    | "info"
    | "warning"
    | "error"
    | "blue"
    | "purple"
    | "pink"
    | "teal"
    | "orange";
}

const statuses = {
  pending: { label: "Pending", icon: TriangleAlert },
  "in-progress": { label: "In progress", icon: CircleDashed },
  submitted: { label: "Submitted", icon: Send },
  "in-review": { label: "In review", icon: SearchCheck },
  success: { label: "Success", icon: CircleCheck },
  failed: { label: "Failed", icon: CircleX },
  expired: { label: "Expired", icon: Clock3 },
};

const styles = {
  pending: "bg-orange-500/10 text-orange-700 dark:text-orange-400",
  "in-progress": "bg-sky-500/10 text-sky-700 dark:text-sky-400",
  submitted: "bg-violet-500/10 text-violet-700 dark:text-violet-400",
  "in-review": "bg-yellow-500/10 text-yellow-700 dark:text-yellow-400",
  success: "bg-green-500/10 text-green-700 dark:text-green-400",
  failed: "bg-red-500/10 text-red-700 dark:text-red-400",
  expired: "bg-neutral-500/10 text-neutral-700 dark:text-neutral-400",
  neutral: "bg-neutral-500/10 text-neutral-700 dark:text-neutral-400",
  info: "bg-sky-500/10 text-sky-700 dark:text-sky-400",
  warning: "bg-amber-500/10 text-amber-700 dark:text-amber-400",
  error: "bg-red-500/10 text-red-700 dark:text-red-400",
  blue: "bg-blue-500/10 text-blue-700 dark:text-blue-400",
  purple: "bg-purple-500/10 text-purple-700 dark:text-purple-400",
  pink: "bg-pink-500/10 text-pink-700 dark:text-pink-400",
  teal: "bg-teal-500/10 text-teal-700 dark:text-teal-400",
  orange: "bg-orange-500/10 text-orange-700 dark:text-orange-400",
};

export const Badge = memo(function Badge({
  children,
  variant = "success",
  className = "",
  ...props
}: BadgeProps = {}) {
  const status = variant in statuses ? statuses[variant as keyof typeof statuses] : undefined;
  const Icon = status?.icon;
  const reducedMotion = useReducedMotion();

  return (
    <motion.span
      initial={reducedMotion ? false : { opacity: 0, y: 20 }}
      whileInView={reducedMotion ? undefined : { opacity: 1, y: 0 }}
      viewport={{ once: true, amount: 0.5 }}
      whileHover={reducedMotion ? undefined : { y: -2, scale: 1.03 }}
      transition={{ duration: reducedMotion ? 0 : 0.35, ease: "easeOut" }}
      className={`inline-flex items-center gap-2 rounded-lg surface-raised surface-status px-3 py-2 typography-label ${styles[variant]} ${className}`}
      {...props}
    >
      {Icon && <Icon aria-hidden="true" className="size-[1.15em] shrink-0" strokeWidth={2.25} />}
      {children ?? status?.label ?? "New release"}
    </motion.span>
  );
});

import { memo, type ComponentProps } from "react";

type ButtonProps = {
  variant?: "primary" | "secondary" | "ghost" | "destructive" | "outline";
} & ((ComponentProps<"button"> & { href?: never }) | (ComponentProps<"a"> & { href: string }));

export function buttonClassName(variant: ButtonProps["variant"] = "primary", className = "") {
  const styles = {
    primary:
      "[--button-color:var(--color-emerald-400)] [--button-top:var(--color-emerald-300)] [--button-stroke-top:var(--color-emerald-200)] [--button-stroke-bottom:var(--color-emerald-700)] text-neutral-950",
    secondary: "[--button-color:var(--secondary)] text-secondary-foreground",
    ghost: "bg-transparent text-foreground hover:bg-muted",
    destructive: "[--button-color:var(--destructive)] text-destructive-foreground",
    outline:
      "[--button-color:var(--background)] [--button-top:var(--background)] [--button-bottom:var(--muted)] [--button-stroke-top:var(--border)] [--button-stroke-bottom:color-mix(in_srgb,var(--foreground)_25%,var(--border))] text-foreground hover:[--button-top:var(--muted)]",
  };
  const surface =
    variant === "ghost"
      ? ""
      : "border border-transparent [background:linear-gradient(to_bottom,var(--button-top,color-mix(in_srgb,var(--button-color)_88%,white)),var(--button-bottom,var(--button-color)))_padding-box,linear-gradient(to_bottom,var(--button-stroke-top,color-mix(in_srgb,var(--button-color)_65%,white)),var(--button-stroke-bottom,color-mix(in_srgb,var(--button-color)_65%,black)))_border-box] shadow-[0_1px_2px_rgb(0_0_0/0.12),0_4px_8px_-2px_rgb(0_0_0/0.18)] hover:[--button-top:color-mix(in_srgb,var(--button-color)_78%,white)]";
  return `inline-flex min-h-11 items-center justify-center gap-2 rounded-lg px-5 py-2 text-sm font-semibold  transition-colors focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ring disabled:pointer-events-none disabled:opacity-50 ${surface} ${styles[variant] ?? styles.primary} ${className}`;
}

export const Button = memo(function Button({
  children = "Get started",
  variant = "primary",
  className = "",
  ...props
}: ButtonProps = {}) {
  const classes = buttonClassName(variant, className);

  if (props.href !== undefined) {
    return (
      <a className={classes} {...props}>
        {children}
      </a>
    );
  }

  return (
    <button type="button" className={classes} {...props}>
      {children}
    </button>
  );
});

import { memo, type ComponentProps, type ReactNode } from "react";
import { cn } from "cn";

// Legacy content props remain supported for existing consumers.
const cardSizes = {
  sm: "gap-4 px-4 py-4",
  md: "gap-6 px-6 py-6",
} as const;

type CardProps = {
  size?: keyof typeof cardSizes;
  title?: string;
  description?: string;
  footer?: ReactNode;
} & (
  | ({ as?: "article" } & Omit<ComponentProps<"article">, "title">)
  | ({ as: "a" } & Omit<ComponentProps<"a">, "title">)
);

const Card = memo(function Card({
  title,
  description,
  children,
  footer,
  className,
  size = "md",
  ...props
}: CardProps) {
  const hasLegacyContent = Boolean(title || description || footer);
  const classes = cn(
    "group/card flex w-full max-w-sm flex-col rounded-lg surface-raised text-base leading-7",
    "outline-ring focus-visible:outline-[length:var(--focus-ring-width,2px)] focus-visible:outline-offset-[var(--focus-ring-offset,2px)]",
    "[a&]:transition-colors [a&]:duration-[var(--duration-fast,150ms)] [a&]:ease-out [a&]:hover:[--surface-bottom:var(--muted)] motion-reduce:transition-none",
    cardSizes[size],
    className,
  );
  const content = (
    <>
      {(title || description) && (
        <CardHeader>
          {title && <CardTitle>{title}</CardTitle>}
          {description && <CardDescription>{description}</CardDescription>}
        </CardHeader>
      )}
      {hasLegacyContent ? children && <CardContent>{children}</CardContent> : children}
      {footer && <CardFooter>{footer}</CardFooter>}
    </>
  );
  if (props.as === "a") {
    const { as: Tag, ...anchorProps } = props;
    return (
      <Tag data-slot="card" data-size={size} className={classes} {...anchorProps}>
        {content}
      </Tag>
    );
  }
  const { as: Tag = "article", ...articleProps } = props;
  return (
    <Tag data-slot="card" data-size={size} className={classes} {...articleProps}>
      {content}
    </Tag>
  );
});

const CardHeader = memo(function CardHeader({ className, ...props }: ComponentProps<"header">) {
  return (
    <header
      data-slot="card-header"
      className={cn(
        "grid auto-rows-min items-start gap-x-4 gap-y-2 has-[[data-slot=card-action]]:grid-cols-[1fr_auto]",
        className,
      )}
      {...props}
    />
  );
});

const CardTitle = memo(function CardTitle({ className, ...props }: ComponentProps<"h3">) {
  return (
    <h3 data-slot="card-title" className={cn("typography-section-title", className)} {...props} />
  );
});

const CardDescription = memo(function CardDescription({
  className,
  ...props
}: ComponentProps<"p">) {
  return (
    <p
      data-slot="card-description"
      className={cn("col-start-1", "typography-body", className)}
      {...props}
    />
  );
});

const CardAction = memo(function CardAction({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      data-slot="card-action"
      className={cn("col-start-2 row-span-2 row-start-1 self-start justify-self-end", className)}
      {...props}
    />
  );
});

const CardContent = memo(function CardContent({ className, ...props }: ComponentProps<"div">) {
  return <div data-slot="card-content" className={className} {...props} />;
});

const CardFooter = memo(function CardFooter({ className, ...props }: ComponentProps<"footer">) {
  return (
    <footer
      data-slot="card-footer"
      className={cn("flex items-center border-t border-border pt-4", className)}
      {...props}
    />
  );
});

export { Card, CardAction, CardContent, CardDescription, CardFooter, CardHeader, CardTitle };
